#include <memory>
#include <iostream>

void transfer_ownership() {
    std::auto_ptr<int> p(new int(42));
    std::auto_ptr<int> q;

    std::cout << "P before: " << (p.get() ? *p : -1) << "\n";
    q = p; // Ownership transfer: P is nullified

    // P is now NULL
    std::cout << "P after assignment: " << (p.get() ? *p : 0) << " (NULL)\n";
    std::cout << "Q after assignment: " << (q.get() ? *q : 0) << " (Owned)\n";
}
